export function decodeResponse<T>(body: unknown): T {
  if (typeof body !== 'object' || body === null) throw new Error('Invalid daemon response');
  const envelope = body as { protocol?: { major?: number; minor?: number }; value?: unknown };
  if (envelope.protocol?.major !== PROTOCOL.major || envelope.protocol?.minor !== PROTOCOL.minor || !('value' in envelope)) throw new Error('Incompatible daemon protocol');
  return envelope.value as T;
}
